sealed class RecordingDelegationRegister : IDelegationRegister
{
    private readonly bool _result;

    public RecordingDelegationRegister(bool result)
    {
        _result = result;
    }

    public int CallCount { get; private set; }
    public List<string> Arguments { get; } = new List<string>();

    public bool HasDelegation(string principalId, string resourceId, string action)
    {
        CallCount++;
        Arguments.Add(principalId);
        Arguments.Add(resourceId);
        Arguments.Add(action);
        return _result;
    }
}

